export const moduleByCode = (code: string) => MODULES.find((m) => m.code.toLowerCase() === code.toLowerCase())
export const groupOf = (m: Module) => GROUPS.find((g) => g.code === m.group)!
export const releaseCount = (r: Release) => MODULES.reduce((n, m) => n + m.subs.filter((s) => s.release === r).length, 0)
